gameover:
// A single death lifecycle: freeze the last frame and return after three seconds.
let gameOverPending=false,gameOverTimer=null;
function clearGameOver(){
 clearTimeout(gameOverTimer);gameOverTimer=null;gameOverPending=false;
 document.dispatchEvent(new Event('gameoverclose'));
}
function beginGameOver(){
 if(!started||gameOverPending)return;
 started=false;window.gameAudioStarted=false;gameAudio.pause();
 keys.left=keys.right=keys.fire=false;drag=null;tilt={x:0,y:0};
 document.getElementById('exitGame').classList.add('hidden');
 draw();gameOverPending=true;
 document.dispatchEvent(new CustomEvent('gameover',{detail:{score}}));
 gameOverTimer=setTimeout(()=>{
  clearGameOver();
  menu.querySelector('h1').textContent='🚁 귀염 헬기 슈팅';
  menu.classList.remove('hidden');drawChoices();
 },3000);
}
addEventListener('resize',()=>{if(gameOverPending)draw()});
